What is the output of the following C++ code snippet?

```cpp
#include <iostream>
struct Base {
    virtual void print() { std::cout << "Base "; }
};
struct Derived : Base {
    void print() { std::cout << "Derived "; }
};
int main() {
    Derived d;
    Base b = d;
    b.print();
    Base *bp = &d;
    bp->print();
    return 0;
}
```

